// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure the caller is not the current owner, so the original contract should reject the change
        vm.assume(caller != c.owner());
        // Ensure newOwner is a different address from the current owner to make the property observable
        vm.assume(newOwner != c.owner());

        // Record the current owner before the call
        address originalOwner = c.owner();

        // Attempt to change the owner from the non-owner caller
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            // If the call reverts, the owner should remain unchanged
            ok = false;
        }

        // Assert: If the caller is not the owner, the owner MUST stay the same after the call.
        // The reference contract enforces this via onlyOwner (reverts or returns false),
        // the buggy version allows anyone to change it, so owner differs for some input.
        assertTrue(!ok || c.owner() == originalOwner);
    }
}

